import assert from'node:assert/strict';import{legacy2019PmIntegrationModel}from'./legacy-2019-pm-integration-oracle';
const decode=(s:string)=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&amp;/g,'&');const plain=(s:string)=>decode(s.replace(/<[^>]*>/g,''));
export function readLegacy2019PmIntegrationTable(html:string,values:number[]){const m=legacy2019PmIntegrationModel(values),head=html.match(/<thead>([\s\S]*?)<\/thead>/)![1],rows=[...head.matchAll(/<tr>([\s\S]*?)<\/tr>/g)].map(r=>[...r[1].matchAll(/<th\b([^>]*)>([\s\S]*?)<\/th>/g)].map(c=>({attrs:c[1],text:plain(c[2])})));assert.equal(rows.length,2);assert.deepEqual(rows.map(r=>r.map(c=>c.text)),[['製造工場','事業部'],['P事業部','Q事業部','R事業部','S事業部']]);assert(rows[0][0].attrs.includes('rowSpan="2"')||rows[0][0].attrs.includes('rowspan="2"'));assert(rows[0][1].attrs.includes('colSpan="4"')||rows[0][1].attrs.includes('colspan="4"'));assert(rows[0][1].attrs.includes('scope="colgroup"'));const body=html.match(/<tbody>([\s\S]*?)<\/tbody>/)![1],data=[...body.matchAll(/<tr>([\s\S]*?)<\/tr>/g)].map(r=>[...r[1].matchAll(/<t[hd]\b[^>]*>([\s\S]*?)<\/t[hd]>/g)].map(c=>plain(c[1])));assert.deepEqual(data,[...m.cells.map((r,i)=>['HIJKLM'[i]+'製造工場',...r.map(v=>v===null?'−':String(v))]),['合計',...m.totals.map(String)]]);assert.equal(data.flat().filter(s=>s==='−').length,17);assert(plain(html).includes('当該製造工場が当該事業部の製品を製造していない'));assert(plain(html).includes('単位：億円'));return{headerRows:2,dataRows:7,valueCells:28,positiveCells:7,dashes:17};}
